use super::*;
use super::exact_cursor::{advance_actual,decoded_pcm,OFFSET};
#[test]
fn regenerated_logically_equal_saved_maps_have_one_stable_native_staging_key(){
 let(f,p,save,expected)=media_fixture_options(false,false,Some(true));let game=&f.app.world().resource::<VnEngine>().0;game.video_views().unwrap();let host=prepare_selected_language(f.app.world(),&expected).unwrap();let mut keys=std::collections::HashSet::new();
 for _ in 0..64{let core=game.prepare_save15_with_locale(&p,save.clone(),Some(host.locale().clone())).unwrap();assert_eq!(core.render_batch().state.vars.len(),2);keys.insert(crate::native_video::key_for_test(&core).unwrap());}
 assert_eq!(keys.len(),1,"HashMap random iteration must not revoke equal pending native data");
 let core=game.prepare_save15_with_locale(&p,save.clone(),Some(host.locale().clone())).unwrap();let(first,reordered,reversed_array)=crate::native_video::key_contrasts_for_test(&core).unwrap();assert_eq!(first,reordered);assert_ne!(first,reversed_array);assert!(crate::native_video::prepare_restore(f.app.world(),&core).unwrap().is_none());let initial=crate::native_video::pending_source_for_test(f.app.world()).unwrap();
 for _ in 0..32{let core=game.prepare_save15_with_locale(&p,save.clone(),Some(host.locale().clone())).unwrap();if let Some(ready)=crate::native_video::prepare_restore(f.app.world(),&core).unwrap(){drop(ready);break;}let current=crate::native_video::pending_source_for_test(f.app.world()).unwrap();assert!(std::sync::Weak::ptr_eq(&initial,&current),"Equal maps must retain the same actual Pending worker");assert!(!current.upgrade().unwrap().load(std::sync::atomic::Ordering::Acquire));}
}
fn capture(f:&mut Fixture,p:&rvn_parser::ParsedProgram)->rvn_core::save::consumer_checkpoint::Save15{
 crate::native_video::draw_current_for_test(f.app.world_mut());crate::native_video::capture_save15(f.app.world(),p,None,1,"actual mask/terminal checkpoint".into()).unwrap()
}
fn cold(f:&mut Fixture,p:&rvn_parser::ParsedProgram){
 crate::native_video::clear_current_for_cold_test(f.app.world_mut());let old=&f.app.world().resource::<VnEngine>().0;let mut locale=old.locale.as_ref().unwrap().clone();locale.set_language("en").unwrap();let game=Engine::from_program_with_persistent_and_text_context(p.clone(),BevyRenderer::new(),8,HashMap::new(),rvn_core::TextRuntimeContext::new(old.text_resources().clone(),Some(locale))).unwrap();f.app.world_mut().insert_resource(VnEngine(game));f.app.world_mut().resource_mut::<crate::systems::settings_menu::Settings>().language="en".into();
}
fn restore(f:&mut Fixture,p:&rvn_parser::ParsedProgram,save:&rvn_core::save::consumer_checkpoint::Save15){let mut expected=portable_receipt(f.app.world()).unwrap();expected.locales=save.locale.as_ref().unwrap().clone();let plan=ready_plan(f,p,save,&expected);crate::atomic_text_restore::commit(f.app.world_mut(),plan).unwrap();}
#[test]
fn exact_mask_preroll_installs_the_actual_composed_pixels_and_saved_right_before_return(){
 let(mut f,p,_,_)=media_fixture(true,true);let pcm=decoded_pcm(&f);let audio=crate::native_video::start_current_for_test(f.app.world_mut()).unwrap();audio.0.lock().unwrap().running=true;let mut source=audio.decoder();advance_actual(&mut f,&audio,&mut source,&pcm);let pixels=crate::native_video::current_pixels_for_test(f.app.world());assert_eq!(pixels.len(),320*180*4);assert!(pixels.chunks_exact(4).any(|p|p[3]<255));let save=capture(&mut f,&p);assert!(save.native_media_checkpoint.as_ref().unwrap()[0].mask.is_some());let save=rvn_core::save::consumer_checkpoint::Save15::decode(&save.encode().unwrap()).unwrap();drop(source);drop(audio);cold(&mut f,&p);restore(&mut f,&p,&save);
 assert_eq!(crate::native_video::current_pixels_for_test(f.app.world()),pixels,"Mask must already be installed at atomic return, not a later tick");let rows=crate::native_video::restored_sources_for_test(f.app.world());let audio=rows[0].1.as_ref().unwrap();audio.0.lock().unwrap().running=true;let mut source=audio.decoder();assert_eq!(source.next(),Some(0.0));for expected in &pcm[OFFSET..OFFSET+64]{assert_eq!(source.next().unwrap().to_bits(),expected.to_bits());}
}
#[test]
fn corrupt_mask_locator_asset_stream_pts_and_ordinal_refuse_without_partial_world_mutation(){
 for corruption in 0..5{let(mut f,p,_,_)=media_fixture(true,true);let pcm=decoded_pcm(&f);let audio=crate::native_video::start_current_for_test(f.app.world_mut()).unwrap();audio.0.lock().unwrap().running=true;let mut source=audio.decoder();advance_actual(&mut f,&audio,&mut source,&pcm);let mut save=capture(&mut f,&p);let mask=save.native_media_checkpoint.as_mut().unwrap()[0].mask.as_mut().unwrap();match corruption{0=>mask.source_locator="other.webm".into(),1=>mask.asset_sha256[0]^=1,2=>mask.profile.video_stream+=1,3=>mask.picture.pts+=1,_=>mask.picture.ordinal+=1};let before=atomic_world_before(&f);let entities=f.app.world().entities().len();let mut expected=portable_receipt(f.app.world()).unwrap();expected.locales=save.locale.as_ref().unwrap().clone();let deadline=Instant::now()+Duration::from_secs(20);loop{match crate::atomic_text_restore::prepare(f.app.world(),&p,save.clone(),&expected){Ok(_)=>panic!("Corrupt mask was admitted"),Err(e)if e.contains("still staging")=>{},Err(_)=>break}assert!(Instant::now()<deadline);std::thread::sleep(Duration::from_millis(2));}assert_eq!(atomic_world_before(&f),before);assert_eq!(f.app.world().entities().len(),entities);assert!(!audio.0.lock().unwrap().revoked);}
}
#[test]
fn changed_actual_mask_after_ready_refuses_before_core_settings_or_old_reader_retirement(){
 let(mut f,p,_,_)=media_fixture(true,true);let pcm=decoded_pcm(&f);let audio=crate::native_video::start_current_for_test(f.app.world_mut()).unwrap();audio.0.lock().unwrap().running=true;let mut source=audio.decoder();advance_actual(&mut f,&audio,&mut source,&pcm);let save=capture(&mut f,&p);let mut expected=portable_receipt(f.app.world()).unwrap();expected.locales=save.locale.as_ref().unwrap().clone();let plan=ready_plan(&mut f,&p,&save,&expected);let before=atomic_world_before(&f);let entities=f.app.world().entities().len();let mut bytes=CLIP.to_vec();let last=bytes.len()-1;bytes[last]^=1;fs::write(f.root.join("assets/mask.webm"),bytes).unwrap();assert!(crate::atomic_text_restore::commit(f.app.world_mut(),plan).is_err());assert_eq!(atomic_world_before(&f),before);assert_eq!(f.app.world().entities().len(),entities);assert!(!audio.0.lock().unwrap().revoked);assert!(source.next().is_some());
}
fn consume_to_actual_eof(f:&mut Fixture,audio:&crate::video_audio::VideoAudio,source:&mut crate::video_audio::Samples,pcm:&[f32]){
 let deadline=Instant::now()+Duration::from_secs(20);loop{assert!(Instant::now()<deadline);let before=audio.0.lock().unwrap().delivered_sample_offset().unwrap()as usize;match source.next(){Some(sample)=>{let after=audio.0.lock().unwrap().delivered_sample_offset().unwrap()as usize;if after==before+1{assert_eq!(sample.to_bits(),pcm[before].to_bits());}else{assert_eq!(before,after);assert_eq!(sample,0.0);std::thread::sleep(Duration::from_millis(1));}if after%128==0||after==before{crate::native_video::pump_draw_report_current_for_test(f.app.world_mut()).unwrap();}},None=>{assert_eq!(before,pcm.len());break}}}
 crate::native_video::pump_draw_report_current_for_test(f.app.world_mut()).unwrap();crate::native_video::finish_actual_current_for_test(f.app.world_mut()).unwrap();
}
#[test]
fn actual_terminal_keep_last_restores_frozen_mask_or_picture_without_sound_or_end_replay(){
 for mask in [false,true]{let(mut f,p,_,_)=media_fixture_options(true,mask,Some(true));let pcm=decoded_pcm(&f);let audio=crate::native_video::start_current_for_test(f.app.world_mut()).unwrap();audio.0.lock().unwrap().running=true;let mut source=audio.decoder();consume_to_actual_eof(&mut f,&audio,&mut source,&pcm);assert_eq!(f.app.world().resource::<VnEngine>().0.state.vars["ends"],rvn_parser::Value::Int(1));let pixels=crate::native_video::current_pixels_for_test(f.app.world());let save=capture(&mut f,&p);let row=&save.native_media_checkpoint.as_ref().unwrap()[0];assert!(row.audio.is_none());assert_eq!(row.mask.is_some(),mask);drop(source);drop(audio);cold(&mut f,&p);assert_eq!(f.app.world().resource::<VnEngine>().0.state.vars["ends"],rvn_parser::Value::Int(0));restore(&mut f,&p,&save);assert_eq!(crate::native_video::current_pixels_for_test(f.app.world()),pixels);assert_eq!(f.app.world().resource::<VnEngine>().0.state.vars["ends"],rvn_parser::Value::Int(1));assert!(crate::native_video::restored_sources_for_test(f.app.world())[0].1.is_none());crate::native_video::draw_current_for_test(f.app.world_mut());assert_eq!(crate::native_video::current_pixels_for_test(f.app.world()),pixels);assert_eq!(f.app.world().resource::<VnEngine>().0.state.vars["ends"],rvn_parser::Value::Int(1));}
}
#[test]
fn actual_terminal_without_retained_pixels_needs_no_fake_media_cursor_and_replays_nothing(){
 let(mut f,p,_,_)=media_fixture_options(true,false,Some(false));let pcm=decoded_pcm(&f);let audio=crate::native_video::start_current_for_test(f.app.world_mut()).unwrap();audio.0.lock().unwrap().running=true;let mut source=audio.decoder();consume_to_actual_eof(&mut f,&audio,&mut source,&pcm);let save=capture(&mut f,&p);assert!(save.native_media_checkpoint.as_ref().unwrap().is_empty());drop(source);drop(audio);cold(&mut f,&p);restore(&mut f,&p,&save);let rows=crate::native_video::restored_sources_for_test(f.app.world());assert!(rows[0].1.is_none());assert_eq!((rows[0].2,rows[0].3),(1,1));assert_eq!(f.app.world().resource::<VnEngine>().0.state.vars["ends"],rvn_parser::Value::Int(1));
}
